B.ago={"restricted-exhaust-airflow":0,"clogged-lint-pathway":1,"thermal-fuse-open":2,"accessible-thermal-reset":3,"motor-overheat-protector-open":4,"heating-element-failed":5,"electric-supply-connection-fault":6,"broken-drive-belt":7,"worn-drum-rollers":8,"idler-pulley-wear":9,"door-switch-failure":10,"motor-failure":11}
B.a_e=s([u._,u.c,u.a,"Unplug the dryer (or switch off its breaker) before moving it.","Restore power, run a short heat cycle, and re-check exterior airflow."],t.s)
B.pr=s([B.mK,B.rx],t.c)
B.SH=new A.c5("restricted-exhaust-airflow",u.z,u.h0,B.a_e,B.j,B.pr,B.a0,!0,!0)
B.a0J=s(["Unplug the dryer before inspecting the lint housing.","Clean the lint filter and any safely accessible lint around the slot.","Do not dismantle sealed cabinets or wiring.","Restore power and run a small test load on a heat cycle."],t.s)
B.a0Y=s([B.mK,B.rD],t.c)
B.SO=new A.c5("clogged-lint-pathway",u.gS,u.cR,B.a0J,B.j,B.a0Y,B.a0,!0,!0)
